const { chromium } = require('playwright');
const fs   = require('fs');
const path = require('path');

const BASE_URL       = 'https://staging.247software.com';
const ET_URL         = `${BASE_URL}/#/setup-navigation/event-types`;
const USERNAME       = 'Pranay';
const PASSWORD       = 'Pranay@1234';
const SCREENSHOTS_DIR = path.resolve(__dirname, '../screenshots');
const LOGS_DIR        = path.resolve(__dirname, '../logs');

[SCREENSHOTS_DIR, LOGS_DIR].forEach(d => { if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true }); });

const results = [];

function record(id, title, status, detail, screenshot) {
  const entry = {
    id, title, status,
    detail:     detail     ? String(detail).slice(0, 600) : null,
    screenshot: screenshot || null,
    timestamp:  new Date().toISOString()
  };
  results.push(entry);
  const label = status === 'PASS' ? 'PASS' : status === 'SKIP' ? 'SKIP' : 'FAIL';
  console.log(`[${label}] ${id} — ${title}${detail ? ' | ' + String(detail).slice(0, 140) : ''}`);
}

async function launch() {
  return chromium.launch({ headless: true, args: ['--no-sandbox', '--disable-setuid-sandbox'] });
}

async function loginAndNavigate(browser, url) {
  const ctx  = await browser.newContext({ ignoreHTTPSErrors: true });
  const page = await ctx.newPage();
  page.setDefaultTimeout(25000);

  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded', timeout: 30000 });
  await page.waitForTimeout(1500);

  await page.fill('#username', USERNAME);
  await page.fill('#password', PASSWORD);
  await Promise.all([
    page.waitForResponse(r => r.url().includes('/authenticate') && r.status() === 200, { timeout: 20000 }),
    page.click('#login_btn')
  ]);
  await page.waitForTimeout(4000);

  if (url) {
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 20000 });
    await page.waitForTimeout(4000);
  }
  return page;
}

async function ss(page, id) {
  const p = path.join(SCREENSHOTS_DIR, `${id}.png`);
  try { await page.screenshot({ path: p, fullPage: true }); } catch (_) {}
  return p;
}

// Wait for AG Grid to fully render
async function waitForGrid(page) {
  try {
    await page.waitForSelector('.ag-row', { timeout: 10000 });
  } catch (_) {}
  await page.waitForTimeout(1000);
}

// ─── TC-001: Navigate to Event Types from Setup ────────────────────────────

async function TC001() {
  const id = 'TC-001'; const title = 'Navigate to Event Types from Setup menu';
  const browser = await launch();
  try {
    const page = await loginAndNavigate(browser, null);
    // Navigate via Setup menu link
    await page.goto(`${BASE_URL}/#/setup`, { waitUntil: 'domcontentloaded', timeout: 20000 });
    await page.waitForTimeout(3000);

    // Click Event Types link in Setup nav
    const etLink = page.locator('a[href="#/setup-navigation/event-types"], label[id="/setupnavigation/eventtypes"]').first();
    await etLink.waitFor({ state: 'visible', timeout: 10000 });
    await etLink.click();
    await page.waitForTimeout(3000);

    const content = await page.content();
    const isOnPage = content.includes('Event Types') || page.url().includes('event-types');
    const shot = await ss(page, id);
    record(id, title, isOnPage ? 'PASS' : 'FAIL', isOnPage ? `Navigated to: ${page.url()}` : 'Event Types page not detected', shot);
  } catch (e) {
    record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`));
  } finally { await browser.close(); }
}

