// ─── TC-003: Create new Event Type ─────────────────────────────────────────

async function TC003() {
  const id = 'TC-003'; const title = 'Create a new Event Type with valid data';
  const browser = await launch();
  try {
    const page = await loginAndNavigate(browser, ET_URL);
    await waitForGrid(page);

    // Click the Add (+) button
    const addBtn = page.locator('i.fas.fa-plus-circle, .fa-plus-circle').first();
    const addBtnVisible = await addBtn.isVisible({ timeout: 8000 }).catch(() => false);

    if (!addBtnVisible) {
      const shot = await ss(page, id);
      return record(id, title, 'SKIP', 'Add (plus) button not found on page', shot);
    }
    await addBtn.click();
    await page.waitForTimeout(3000);

    // Capture any API call for save
    let apiSuccess = false;
    page.on('response', r => {
      if ((r.url().includes('eventType') || r.url().includes('Event')) && r.status() < 400) {
        apiSuccess = true;
      }
    });

    // Fill the form fields
    const nameInput = page.locator('input[type="text"]:visible, input[placeholder*="ype"]:visible, input[placeholder*="ame"]:visible').first();
    const nameVisible = await nameInput.isVisible({ timeout: 6000 }).catch(() => false);

    if (!nameVisible) {
      const shot = await ss(page, id);
      return record(id, title, 'SKIP', 'Name input field not found in create form', shot);
    }

    await nameInput.fill('TestEventType_Auto');
    await page.waitForTimeout(500);

    // Click Save
    const saveBtn = page.locator('button.modal-save-button, button.modal-confirm-button, button:has-text("Save")').first();
    await saveBtn.waitFor({ state: 'visible', timeout: 5000 });
    await saveBtn.click();
    await page.waitForTimeout(4000);

    const bodyText = await page.evaluate(() => document.body.innerText);
    const created = bodyText.includes('TestEventType_Auto') ||
                    bodyText.toLowerCase().includes('success') ||
                    bodyText.toLowerCase().includes('saved') ||
                    apiSuccess;

    const shot = await ss(page, id);
    record(id, title, created ? 'PASS' : 'FAIL',
      created ? 'Event type created and confirmed' : 'Creation not confirmed in page', shot);
  } catch (e) {
    record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`));
  } finally { await browser.close(); }
}

