// ─── TC-016: UI elements rendered correctly ───────────────────────────────

async function TC016() {
  const id = 'TC-016'; const title = 'Event Types page UI elements are correctly rendered';
  const browser = await launch();
  try {
    const page = await loginAndNavigate(browser, ET_URL);
    await waitForGrid(page);

    const bodyText = await page.evaluate(() => document.body.innerText);
    const hasH4Title = await page.locator('h4.main-title-width').isVisible({ timeout: 5000 }).catch(() => false);
    const pageTitle  = await page.locator('h4.main-title-width').textContent({ timeout: 3000 }).catch(() => '');
    const hasBreadcrumb = bodyText.includes('Home') && bodyText.includes('Setup');
    const hasColumns    = bodyText.includes('Event Type') && bodyText.includes('Description');

    const shot = await ss(page, id);
    const pass = hasH4Title && pageTitle.includes('Event Types') && hasColumns;
    record(id, title, pass ? 'PASS' : 'FAIL',
      `h4="${pageTitle.trim()}" breadcrumb=${hasBreadcrumb} columns=${hasColumns}`, shot);
  } catch (e) {
    record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`));
  } finally { await browser.close(); }
}

// ─── TC-017: Max character name boundary ──────────────────────────────────

async function TC017() {
  const id = 'TC-017'; const title = 'Create Event Type with maximum allowed character name';
  const browser = await launch();
  try {
    const page = await loginAndNavigate(browser, ET_URL);
    await waitForGrid(page);

    const addBtn = page.locator('i.fas.fa-plus-circle, .fa-plus-circle').first();
    if (!await addBtn.isVisible({ timeout: 8000 }).catch(() => false)) {
      return record(id, title, 'SKIP', 'Add button not found', await ss(page, id));
    }
    await addBtn.click();
    await page.waitForTimeout(3000);

    const nameInput = page.locator('input[type="text"]:visible').first();
    if (!await nameInput.isVisible({ timeout: 5000 }).catch(() => false)) {
      return record(id, title, 'SKIP', 'Name input not found', await ss(page, id));
    }

    const longName = 'B'.repeat(255);
    await nameInput.fill(longName);
    const actualValue = await nameInput.inputValue();

    const saveBtn = page.locator('button.modal-save-button, button:has-text("Save")').first();
    await saveBtn.waitFor({ state: 'visible', timeout: 5000 });
    await saveBtn.click();
    await page.waitForTimeout(4000);

    const bodyText = await page.evaluate(() => document.body.innerText);
    const acceptableOutcome = actualValue.length <= 255 &&
                              (bodyText.toLowerCase().includes('success') ||
                               bodyText.toLowerCase().includes('saved') ||
                               bodyText.toLowerCase().includes('error') ||
                               bodyText.toLowerCase().includes('limit'));

    const shot = await ss(page, id);
    record(id, title, acceptableOutcome ? 'PASS' : 'FAIL',
      `Filled length: ${actualValue.length}/255. Acceptable outcome: ${acceptableOutcome}`, shot);
  } catch (e) {
    record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`));
  } finally { await browser.close(); }
}

// ─── TC-018: Performance threshold ────────────────────────────────────────

async function TC018() {
  const id = 'TC-018'; const title = 'Event Types page loads within acceptable performance threshold';
  const browser = await launch();
  try {
    const page = await loginAndNavigate(browser, null);

    const start = Date.now();
    await page.goto(ET_URL, { waitUntil: 'domcontentloaded', timeout: 20000 });
    await waitForGrid(page);
    const loadTime = Date.now() - start;

    const threshold = 5000;
    const shot = await ss(page, id);
    record(id, title, loadTime <= threshold ? 'PASS' : 'FAIL',
      `Load time: ${loadTime}ms (threshold: ${threshold}ms)`, shot);
  } catch (e) {
    record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`));
  } finally { await browser.close(); }
}

